namespace sv_5a7cf5186eff4e31b5a88648973558b4.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service holding the current warehouse selection for a single user circuit.
/// Components subscribe to OnChange to react when the warehouse is switched.
/// </summary>
public class WarehouseState
{
    private static readonly List<WarehouseInfo> _availableWarehouses =
    [
        new() { Id = "wh-a", Name = "Warehouse A" },
        new() { Id = "wh-b", Name = "Warehouse B" },
        new() { Id = "wh-c", Name = "Warehouse C" },
        new() { Id = "wh-d", Name = "Warehouse D" },
    ];

    public IReadOnlyList<WarehouseInfo> AvailableWarehouses => _availableWarehouses;

    public string CurrentWarehouseId { get; private set; } = _availableWarehouses[0].Id;

    public string CurrentWarehouseName =>
        _availableWarehouses.FirstOrDefault(w => w.Id == CurrentWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (warehouseId == CurrentWarehouseId) return;
        CurrentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_5a7cf5186eff4e31b5a88648973558b4.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each user circuit gets its own instance (scoped), so managers see independent data.
/// Polling starts when the first subscriber registers and stops when all unsubscribe.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();

    private CancellationTokenSource? _cts;
    private Task? _pollingTask;
    private int _subscriberCount;
    private readonly object _lock = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must wrap StateHasChanged
    /// in InvokeAsync since this fires from a background thread.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning a random low-stock count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Starts the polling loop if not already running.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _cts = new CancellationTokenSource();
                _pollingTask = PollAsync(_cts.Token);
            }
        }
    }

    /// <summary>
    /// Call when a component that requested polling is disposed/leaves.
    /// Stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _cts?.Cancel();
                _cts?.Dispose();
                _cts = null;
                _pollingTask = null;
            }
        }
    }

    private async Task PollAsync(CancellationToken token)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        // Fetch immediately on start
        await FetchAndNotifyAsync();

        try
        {
            while (await timer.WaitForNextTickAsync(token))
            {
                await FetchAndNotifyAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh the alert count
        _ = Task.Run(async () => await FetchAndNotifyAsync());
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

