public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service holding the current warehouse selection for a single user circuit.
/// Components subscribe to OnChange to react when the warehouse is switched.
/// </summary>
public class WarehouseState
{
    private static readonly List<WarehouseInfo> _availableWarehouses =
    [
        new() { Id = "wh-a", Name = "Warehouse A" },
        new() { Id = "wh-b", Name = "Warehouse B" },
        new() { Id = "wh-c", Name = "Warehouse C" },
        new() { Id = "wh-d", Name = "Warehouse D" },
    ];

    public IReadOnlyList<WarehouseInfo> AvailableWarehouses => _availableWarehouses;

    public string CurrentWarehouseId { get; private set; } = _availableWarehouses[0].Id;

    public string CurrentWarehouseName =>
        _availableWarehouses.FirstOrDefault(w => w.Id == CurrentWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (warehouseId == CurrentWarehouseId) return;
        CurrentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

