                    <span class="text-muted fs-6">(@WarehouseState.CurrentWarehouseId)</span>
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @(AlertService.CurrentLowStockCount > 5 ? "border-danger" : "border-success")">
